'use client';

import {
  useCallback,
  useEffect,
  useMemo,
  useState,
} from 'react';

import Player from './Player';
import Room from './Room';
import { clues } from '@/data/clues';
import ChallengeModal from './ChallengeModal';

import { challenges } from '@/data/challenges';
import { layout1Objects } from '@/data/layout1Objects';
import { layout2Objects } from '@/data/layout2Objects';
import { layout3Objects } from '@/data/layout3Objects';
import { layout4Objects } from '@/data/layout4Objects';

import {
  LayoutId,
  RoomObject,
  Direction,
} from '@/data/types';

const SPEED = 0.25;

export default function Game() {

  /*
   * =========================================================
   * GAME STATE
   * =========================================================
   */

  const [layout, setLayout] =
    useState<LayoutId>(1);

  const [pos, setPos] =
    useState({
      x: 50,
      y: 75,
    });

  const [direction, setDirection] =
    useState<Direction>('down');

  const [walking, setWalking] =
    useState(false);

  const [frame, setFrame] =
    useState(0);

  const [keys, setKeys] =
    useState<Record<string, boolean>>({});

  const [collectedClues, setCollectedClues] =
    useState<string[]>([]);

  const [activeClue, setActiveClue] =
    useState<string | null>(null);

  const [solved, setSolved] =
    useState<string[]>([]);

  const [challenge, setChallenge] =
    useState<string | null>(null);

  const [choice, setChoice] =
    useState<string | number | null>(null);

  const [shortAnswer, setShortAnswer] =
    useState('');

  const [feedback, setFeedback] =
    useState<
      'correct' | 'wrong' | null
    >(null);

  /*
   * Fake interaction popup
   */

  const [fakeMessage, setFakeMessage] =
    useState<string | null>(null);

  const [passwordInput, setPasswordInput] =
  useState('');

const [passwordOpen, setPasswordOpen] =
  useState(false);

const [teacherDeskUnlocked, setTeacherDeskUnlocked] =
  useState(false);

  const [finished, setFinished] =
    useState(false);

  const [transitioning, setTransitioning] =
    useState(false);

  /*
   * =========================================================
   * DEBUG COLLISION MODE
   * =========================================================
   *
   * Press F2 to show/hide collision boxes.
   */

  const [debugCollision, setDebugCollision] =
    useState(false);


  /*
   * =========================================================
   * ACTIVE CHALLENGES
   * =========================================================
   */

  const activeChallenges =
    useMemo(() => {
      return challenges.filter(
        (challengeItem) =>
          challengeItem.layout === layout
      );
    }, [layout]);


  /*
   * =========================================================
   * CURRENT CHALLENGE
   * =========================================================
   */

  const currentChallenge =
    useMemo(() => {
      return (
        challenges.find(
          (challengeItem) =>
            challengeItem.id === challenge
        ) ?? null
      );
    }, [challenge]);


  /*
   * =========================================================
   * CURRENT LAYOUT PROGRESS
   * =========================================================
   */

  const solvedInCurrentLayout =
    useMemo(() => {
      return activeChallenges.filter(
        (challengeItem) =>
          solved.includes(
            challengeItem.id
          )
      ).length;
    }, [
      activeChallenges,
      solved,
    ]);


  /*
   * =========================================================
   * CURRENT LAYOUT COMPLETED
   * =========================================================
   */

  const currentLayoutCompleted =
    useMemo(() => {
      return (
        activeChallenges.length > 0 &&
        activeChallenges.every(
          (challengeItem) =>
            solved.includes(
              challengeItem.id
            )
        )
      );
    }, [
      activeChallenges,
      solved,
    ]);


  /*
   * =========================================================
   * LAYOUT 1 — WHITEBOARD PROGRESS
   * =========================================================
   */

  const whiteboardChallenges =
    useMemo(() => {

      return activeChallenges.filter(
        (challengeItem) =>
          challengeItem.id.startsWith(
            'layout1-whiteboard-'
          )
      );

    }, [
      activeChallenges,
    ]);


  const solvedWhiteboard =
    useMemo(() => {

      return whiteboardChallenges.filter(
        (challengeItem) =>
          solved.includes(
            challengeItem.id
          )
      ).length;

    }, [
      whiteboardChallenges,
      solved,
    ]);


  const whiteboardCompleted =
    whiteboardChallenges.length > 0 &&
    solvedWhiteboard ===
      whiteboardChallenges.length;


  /*
   * =========================================================
   * LAYOUT 1 — DRAWER PROGRESS
   * =========================================================
   */

  const drawerChallenges =
    useMemo(() => {

      return activeChallenges.filter(
        (challengeItem) =>
          challengeItem.id.startsWith(
            'layout1-drawer-'
          )
      );

    }, [
      activeChallenges,
    ]);


  const solvedDrawer =
    useMemo(() => {

      return drawerChallenges.filter(
        (challengeItem) =>
          solved.includes(
            challengeItem.id
          )
      ).length;

    }, [
      drawerChallenges,
      solved,
    ]);


  const drawerCompleted =
    drawerChallenges.length > 0 &&
    solvedDrawer ===
      drawerChallenges.length;


  /*
   * =========================================================
   * DRAWER UNLOCK STATUS
   * =========================================================
   */

  const drawerUnlocked =
    layout !== 1 ||
    whiteboardCompleted;


  /*
   * =========================================================
   * ROOM OBJECTS
   * =========================================================
   */

  const visibleObjects =
    useMemo(() => {

      if (layout === 1) {
        return layout1Objects;
      }

      if (layout === 2) {
        return layout2Objects;
      }

      if (layout === 3) {
        return layout3Objects;
      }

      if (layout === 4) {
        return layout4Objects;
      }

      return [];

    }, [layout]);


  /*
   * =========================================================
   * NEAREST INTERACTIVE OBJECT
   * =========================================================
   */

  const nearObj =
  useMemo(() => {

    let nearest: RoomObject | null = null;

    let bestDistance = 8;

    for (const object of visibleObjects) {

      if (!object.interactive) {
        continue;
      }

      /*
       * Check distance to the NEAREST POINT
       * of the interaction rectangle.
       *
       * This is better than checking only
       * the center of the object.
       */

      const closestX =
        Math.max(
          object.x,
          Math.min(
            pos.x,
            object.x + object.w
          )
        );

      const closestY =
        Math.max(
          object.y,
          Math.min(
            pos.y,
            object.y + object.h
          )
        );

      const distance =
        Math.hypot(
          pos.x - closestX,
          pos.y - closestY
        );

      /*
       * Interaction radius
       */

      if (
        distance <= 6 &&
        distance < bestDistance
      ) {

        bestDistance = distance;
        nearest = object;

      }

    }

    return nearest;

  }, [
    pos.x,
    pos.y,
    visibleObjects,
  ]);


  /*
   * =========================================================
   * GET INTERACTION TYPE
   * =========================================================
   */

  const getInteractionType =
    useCallback(
      (
        object: RoomObject | null
      ) => {

        if (!object) {
          return null;
        }

        const objectId =
          String(object.id ?? '').toLowerCase();

        const objectName =
          String(object.name ?? '').toLowerCase();


        /*
         * WHITEBOARD
         */

        if (
          objectId.includes('whiteboard') ||
          objectName.includes('whiteboard')
        ) {
          return 'whiteboard';
        }


        /*
         * DRAWER
         */

        if (
          objectId.includes('drawer') ||
          objectName.includes('drawer')
        ) {
          return 'drawer';
        }
        /*
 * TEACHER DESK
 */

if (
  objectId === 'l2_teacher_desk' ||
  objectName.includes('teacher desk')
) {
  return 'teacher-desk';
}

        return null;
      },
      []
    );


  /*
   * =========================================================
   * COLLECT CLUE
   * =========================================================
   */

  const collectClue =
    useCallback(
      (object: RoomObject) => {

        if (!object.clueId) {
          return;
        }

        const clue =
          clues.find(
            (clueItem) =>
              clueItem.id === object.clueId
          );

        if (!clue) {
          return;
        }


        /*
         * Already collected
         */

        if (
          collectedClues.includes(clue.id)
        ) {

          setFakeMessage(
            `You already found this clue. The letter ${clue.letter} is saved in your book.`
          );

          return;

        }
        /*
 * =========================================================
 * LAYOUT 2 — TEACHER DESK PASSWORD
 * =========================================================
 */

const submitTeacherDeskPassword =
  useCallback(() => {

    const password =
      passwordInput
        .trim()
        .toLowerCase();

    if (
      password !== 'medicine'
    ) {

      setFakeMessage(
        'INCORRECT PASSWORD!\n\nThe password is not correct. Collect the hidden clues and try again.'
      );

      return;

    }

    /*
     * Correct password
     */

    setTeacherDeskUnlocked(true);

    setPasswordOpen(false);

    setPasswordInput('');

    setFakeMessage(
      'PASSWORD ACCEPTED!\n\nThe teacher desk is unlocked. Your next healthcare English challenge is ready.'
    );

  }, [
    passwordInput,
  ]);

        /*
         * Save clue
         */

        setCollectedClues(
          (current) => [
            ...current,
            clue.id,
          ]
        );


        /*
         * Show clue message
         */

        setFakeMessage(
          `YOU FOUND A CLUE!\n\nYou found a clue! Save this letter in your book. Maybe it'll be useful.\n\nLETTER: ${clue.letter}`
        );

      },
      [
        collectedClues,
      ]
    );


  /*
   * =========================================================
   * FAKE INTERACTION MESSAGE
   * =========================================================
   */

  const getFakeInteractionMessage =
    useCallback(
      (objectId: string) => {

        switch (objectId) {

          case 'l1-tv':
            return 'The television is turned off.';

          case 'l1-drawer':
            return 'The drawer is empty.';

          case 'l1-chair-left':
            return 'It is a comfortable chair.';

          case 'l1-chair-right':
            return 'It is a comfortable chair.';

          case 'l1-plant':
            return 'The plant looks healthy.';

          case 'l1-blue-board':
            return 'There is nothing useful here yet.';

          case 'l2_projector':
            return 'The classroom projector is mounted above the room.';

          case 'l2_left_curtain':
            return 'The classroom curtain is closed.';

          case 'l2_right_curtain':
            return 'The classroom curtain is closed.';

          case 'l2_wall_decoration_upper':
            return 'A decoration hangs on the classroom wall.';

          case 'l2_whiteboard':
            return 'A board.';

          case 'l2_wall_decoration_lower':
            return 'A dark wall decoration is mounted here.';

          default:
            return 'There is nothing interesting here.';

        }

      },
      []
    );


  /*
   * =========================================================
   * OPEN NEXT CHALLENGE
   * =========================================================
   */

  const openNextChallenge =
    useCallback(
      (
        targetObject?: RoomObject | null
      ) => {

        const object =
          targetObject ?? nearObj;

        if (!object) {
          return;
        }

        const interactionType =
          getInteractionType(object);


        /*
         * =====================================================
         * WHITEBOARD
         * =====================================================
         */

        if (
          layout === 1 &&
          interactionType === 'whiteboard'
        ) {

          const nextWhiteboard =
            whiteboardChallenges.find(
              (challengeItem) =>
                !solved.includes(
                  challengeItem.id
                )
            );


          if (!nextWhiteboard) {

            setFakeMessage(
              'All 5 whiteboard challenges have been completed. The drawer is now unlocked.'
            );

            return;

          }


          setFakeMessage(null);

          setChallenge(
            nextWhiteboard.id
          );

          setChoice(null);

          setShortAnswer('');

          setFeedback(null);

          return;
        }


        /*
         * =====================================================
         * DRAWER
         * =====================================================
         */

        if (
          layout === 1 &&
          interactionType === 'drawer'
        ) {

          if (!whiteboardCompleted) {

            setFakeMessage(
              `The drawer is locked. Complete all ${whiteboardChallenges.length} whiteboard challenges first.`
            );

            return;
          }


          const nextDrawer =
            drawerChallenges.find(
              (challengeItem) =>
                !solved.includes(
                  challengeItem.id
                )
            );


          if (!nextDrawer) {

            setFakeMessage(
              'All 5 drawer challenges have already been completed.'
            );

            return;
          }


          setFakeMessage(null);

          setChallenge(
            nextDrawer.id
          );

          setChoice(null);

          setFeedback(null);

          return;
        }


        /*
         * =====================================================
         * OTHER OBJECTS / OTHER LAYOUTS
         * =====================================================
         */

        const next =
          activeChallenges.find(
            (challengeItem) =>
              !solved.includes(
                challengeItem.id
              )
          );


        if (!next) {
          return;
        }


        setFakeMessage(null);

        setChallenge(
          next.id
        );

        setChoice(null);

        setFeedback(null);

      },
      [
        nearObj,
        getInteractionType,
        layout,
        activeChallenges,
        solved,
        whiteboardChallenges,
        whiteboardCompleted,
        drawerChallenges,
      ]
    );

  /*
 * =========================================================
 * TEACHER DESK PASSWORD
 * =========================================================
 */


  /*
   * =========================================================
   * MOVEMENT + COLLISION
   * =========================================================
   */

  const tryMove =
    useCallback(
      (
        dx: number,
        dy: number
      ) => {

        setPos(
          (current) => {

            const playerW = 2;
            const playerH = 3;


            const collides =
              (
                x: number,
                y: number
              ) => {

                for (
                  const object of visibleObjects
                ) {

                  if (!object.solid) {
                    continue;
                  }

                  const collision =
                    x + playerW / 2 >
                      object.x &&
                    x - playerW / 2 <
                      object.x + object.w &&
                    y + playerH / 2 >
                      object.y &&
                    y - playerH / 2 <
                      object.y + object.h;

                  if (collision) {
                    return true;
                  }

                }

                return false;

              };


            /*
             * HORIZONTAL
             */

            const nx =
              Math.max(
                6,
                Math.min(
                  94,
                  current.x + dx
                )
              );

            const xAllowed =
              !collides(
                nx,
                current.y
              );

            const finalX =
              xAllowed
                ? nx
                : current.x;


            /*
             * VERTICAL
             */

            const ny =
              Math.max(
                12,
                Math.min(
                  89,
                  current.y + dy
                )
              );

            const yAllowed =
              !collides(
                finalX,
                ny
              );

            const finalY =
              yAllowed
                ? ny
                : current.y;


            return {
              x: finalX,
              y: finalY,
            };

          }
        );

      },
      [visibleObjects]
    );


  /*
   * =========================================================
   * KEYBOARD INPUT
   * =========================================================
   */

  useEffect(() => {

    const down =
      (
        event: KeyboardEvent
      ) => {

        const key =
          event.key.toLowerCase();


        /*
         * Prevent page scrolling
         */

        if (
          key === 'arrowup' ||
          key === 'arrowdown' ||
          key === 'arrowleft' ||
          key === 'arrowright' ||
          key === ' ' ||
          key === 'f2'
        ) {

          event.preventDefault();

        }


        /*
         * =====================================================
         * F2 — DEBUG COLLISION
         * =====================================================
         *
         * event.repeat is blocked so holding F2 does not
         * toggle the mode multiple times.
         */

        if (
          key === 'f2' &&
          !event.repeat
        ) {

          setDebugCollision(
            (current) => !current
          );

          return;

        }


        /*
         * Save pressed key
         */

        setKeys(
          (value) => ({
            ...value,
            [key]: true,
          })
        );


        /*
         * =====================================================
         * ESCAPE
         * =====================================================
         */

        if (
          key === 'escape'
        ) {

          event.preventDefault();


          if (challenge) {

            setChallenge(null);

            setChoice(null);

            setFeedback(null);

          }


          if (fakeMessage) {

            setFakeMessage(null);

          }

          return;

        }


        /*
         * =====================================================
         * E — INTERACTION
         * =====================================================
         */

        if (
          key === 'e' &&
          nearObj &&
          !challenge &&
          !fakeMessage &&
          !transitioning
        ) {

          event.preventDefault();


          const interactionType =
            getInteractionType(
              nearObj
            );

          /*
 * TEACHER DESK
 */

if (
  interactionType === 'teacher-desk' &&
  layout === 2
) {

  if (teacherDeskUnlocked) {

    openNextChallenge();

    return;

  }

  setPasswordInput('');

  setPasswordOpen(true);

  return;
}


          /*
           * REAL CHALLENGE
           */

          if (
  interactionType === 'whiteboard' ||
  interactionType === 'drawer'
) {

  openNextChallenge();

  return;

}


/*
 * TEACHER DESK
 */

if (
  interactionType === 'teacher-desk' &&
  layout === 2
) {

  if (teacherDeskUnlocked) {

    openNextChallenge();

    return;

  }

  setPasswordInput('');

  setPasswordOpen(true);

  return;

}


          /*
 * CLUE INTERACTION
 */

if (
  nearObj &&
  nearObj.clueId
) {

  collectClue(
    nearObj
  );

  return;

}

          


          /*
           * FAKE INTERACTION
           */

          setFakeMessage(
            getFakeInteractionMessage(
              nearObj.id
            )
          );

        }

      };


    const up =
      (
        event: KeyboardEvent
      ) => {

        const key =
          event.key.toLowerCase();

        setKeys(
          (value) => ({
            ...value,
            [key]: false,
          })
        );

      };


    const blur =
      () => {

        setKeys({});

      };


    window.addEventListener(
      'keydown',
      down
    );

    window.addEventListener(
      'keyup',
      up
    );

    window.addEventListener(
      'blur',
      blur
    );


    return () => {

      window.removeEventListener(
        'keydown',
        down
      );

      window.removeEventListener(
        'keyup',
        up
      );

      window.removeEventListener(
        'blur',
        blur
      );

    };

  }, [
    challenge,
    fakeMessage,
    nearObj,
    transitioning,
    openNextChallenge,
    getInteractionType,
    getFakeInteractionMessage,
    collectClue,
    teacherDeskUnlocked,
  ]);


  /*
   * =========================================================
   * MOVEMENT LOOP
   * =========================================================
   */

  useEffect(() => {

    let animationFrame = 0;


    const updateMovement =
      () => {

        let dx = 0;

        let dy = 0;


        if (
          keys.w ||
          keys.arrowup
        ) {

          dy -= SPEED;

        }


        if (
          keys.s ||
          keys.arrowdown
        ) {

          dy += SPEED;

        }


        if (
          keys.a ||
          keys.arrowleft
        ) {

          dx -= SPEED;

        }


        if (
          keys.d ||
          keys.arrowright
        ) {

          dx += SPEED;

        }


        const isMoving =
          dx !== 0 ||
          dy !== 0;


        setWalking(
          isMoving
        );


        /*
         * Direction
         */

        if (dx < 0) {

          setDirection(
            'left'
          );

        } else if (dx > 0) {

          setDirection(
            'right'
          );

        } else if (dy < 0) {

          setDirection(
            'up'
          );

        } else if (dy > 0) {

          setDirection(
            'down'
          );

        }


        /*
         * Move only when no popup is open
         */

        if (
          isMoving &&
          !challenge &&
          !fakeMessage &&
          !transitioning
        ) {

          tryMove(
            dx,
            dy
          );

        }


        animationFrame =
          requestAnimationFrame(
            updateMovement
          );

      };


    animationFrame =
      requestAnimationFrame(
        updateMovement
      );


    return () => {

      cancelAnimationFrame(
        animationFrame
      );

    };

  }, [
    keys,
    tryMove,
    challenge,
    fakeMessage,
    transitioning,
  ]);


  /*
   * =========================================================
   * WALKING ANIMATION
   * =========================================================
   */

  useEffect(() => {

    if (!walking) {

      setFrame(0);

      return;

    }


    const timer =
      window.setInterval(
        () => {

          setFrame(
            (current) =>
              current === 0
                ? 1
                : 0
          );

        },
        150
      );


    return () => {

      window.clearInterval(
        timer
      );

    };

  }, [walking]);


  /*
   * =========================================================
   * ROOM TRANSITIONS
   * =========================================================
   */

  useEffect(() => {

    if (transitioning) {
      return;
    }


    /*
     * LAYOUT 1 → 2
     */

    if (
      layout === 1 &&
      currentLayoutCompleted &&
      pos.x < 12 &&
      pos.y > 82
    ) {

      setTransitioning(true);

      window.setTimeout(
        () => {

          setLayout(2);

          setPos({
            x: 50,
            y: 75,
          });

          setDirection('up');

          setChallenge(null);

          setChoice(null);

          setFeedback(null);

          setFakeMessage(null);

          setKeys({});

          setWalking(false);

          setFrame(0);

          setTransitioning(false);

        },
        700
      );

      return;

    }


    /*
     * LAYOUT 2 → 3
     */

    if (
      layout === 2 &&
      currentLayoutCompleted &&
      pos.x < 12 &&
      pos.y > 82
    ) {

      setTransitioning(true);

      window.setTimeout(
        () => {

          setLayout(3);

          setPos({
            x: 50,
            y: 82,
          });

          setDirection('up');

          setChallenge(null);

          setChoice(null);

          setFeedback(null);

          setFakeMessage(null);

          setKeys({});

          setWalking(false);

          setFrame(0);

          setTransitioning(false);

        },
        700
      );

      return;

    }


    /*
     * LAYOUT 3 → 4
     */

    if (
      layout === 3 &&
      currentLayoutCompleted &&
      pos.x > 42 &&
      pos.x < 58 &&
      pos.y < 18
    ) {

      setTransitioning(true);

      window.setTimeout(
        () => {

          setLayout(4);

          setPos({
            x: 19,
            y: 40,
          });

          setDirection('down');

          setChallenge(null);

          setChoice(null);

          setFeedback(null);

          setFakeMessage(null);

          setKeys({});

          setWalking(false);

          setFrame(0);

          setTransitioning(false);

        },
        700
      );

      return;

    }


    /*
     * LAYOUT 4 → 3
     */

    if (
      layout === 4 &&
      currentLayoutCompleted &&
      pos.x >= 12 &&
      pos.x <= 29 &&
      pos.y >= 29 &&
      pos.y <= 32
    ) {

      setTransitioning(true);

      window.setTimeout(
        () => {

          setLayout(3);

          setPos({
            x: 50,
            y: 20,
          });

          setDirection('down');

          setChallenge(null);

          setChoice(null);

          setFeedback(null);

          setFakeMessage(null);

          setKeys({});

          setWalking(false);

          setFrame(0);

          setTransitioning(false);

        },
        700
      );

      return;

    }

  }, [
    pos.x,
    pos.y,
    layout,
    transitioning,
    currentLayoutCompleted,
  ]);


  /*
   * =========================================================
   * FINISH GAME
   * =========================================================
   */

  useEffect(() => {

    if (
      layout === 4 &&
      currentLayoutCompleted
    ) {

      setFinished(true);

    }

  }, [
    layout,
    currentLayoutCompleted,
  ]);


  /*
   * =========================================================
   * SUBMIT CHALLENGE
   * =========================================================
   */

  const continueToWhiteboardQuestions =
    useCallback(() => {

      const firstQuestion =
        whiteboardChallenges.find(
          (challengeItem) =>
            !solved.includes(
              challengeItem.id
            )
        );

      if (!firstQuestion) {
        return;
      }

      setChallenge(
        firstQuestion.id
      );

      setChoice(null);

      setShortAnswer('');

      setFeedback(null);

    }, [
      whiteboardChallenges,
      solved,
    ]);


  const submit =
    useCallback(() => {

      if (!currentChallenge) {
        return;
      }


      /*
       * SHORT ANSWER
       */

      if (
        currentChallenge.type === 'short-answer'
      ) {

        const userAnswer =
          shortAnswer
            .trim()
            .toLowerCase();

        const correctAnswer =
          currentChallenge.answer
            .trim()
            .toLowerCase();

        if (
          userAnswer !== correctAnswer
        ) {

          setFeedback('wrong');

          return;

        }

      }


      /*
       * MULTIPLE CHOICE
       */

      else {

        if (choice === null) {
          return;
        }

        const selectedAnswer =
          String(choice);

        const correctAnswer =
          String(currentChallenge.answer);

        if (
          selectedAnswer !== correctAnswer
        ) {

          setFeedback('wrong');

          return;

        }

      }


      /*
       * CORRECT ANSWER
       */

      setFeedback('correct');


      /*
       * Mark challenge as solved
       */

      setSolved(
        (value) => {

          if (
            value.includes(
              currentChallenge.id
            )
          ) {

            return value;

          }

          return [
            ...value,
            currentChallenge.id,
          ];

        }
      );


      /*
       * Short answer currently stops here.
       */

      if (
        currentChallenge.type === 'short-answer'
      ) {

        return;

      }


      /*
       * Find next question
       */

      window.setTimeout(() => {

        const solvedAfterCurrent =
          solved.includes(
            currentChallenge.id
          )
            ? solved
            : [
                ...solved,
                currentChallenge.id,
              ];


        /*
         * WHITEBOARD
         */

        if (
          currentChallenge.id.startsWith(
            'layout1-whiteboard-'
          )
        ) {

          const nextWhiteboard =
            whiteboardChallenges.find(
              (challengeItem) =>
                !solvedAfterCurrent.includes(
                  challengeItem.id
                )
            );


          if (nextWhiteboard) {

            setChallenge(
              nextWhiteboard.id
            );

            setChoice(null);

            setShortAnswer('');

            setFeedback(null);

            return;

          }


          setChallenge(null);

          setChoice(null);

          setShortAnswer('');

          setFeedback(null);

          setFakeMessage(
            'WHITEBOARD COMPLETE! The drawer is now unlocked. Go to the drawer and press E.'
          );

          return;

        }


        /*
         * DRAWER
         */

        if (
          currentChallenge.id.startsWith(
            'layout1-drawer-'
          )
        ) {

          const nextDrawer =
            drawerChallenges.find(
              (challengeItem) =>
                !solvedAfterCurrent.includes(
                  challengeItem.id
                )
            );


          if (nextDrawer) {

            setChallenge(
              nextDrawer.id
            );

            setChoice(null);

            setShortAnswer('');

            setFeedback(null);

            return;

          }


          setChallenge(null);

          setChoice(null);

          setShortAnswer('');

          setFeedback(null);

          setFakeMessage(
            'DRAWER COMPLETE! All Layout 1 challenges are complete. The exit is now unlocked.'
          );

          return;

        }


        /*
         * OTHER LAYOUTS
         */

        const nextQuestion =
          activeChallenges.find(
            (challengeItem) =>
              !solvedAfterCurrent.includes(
                challengeItem.id
              )
          );


        if (nextQuestion) {

          setChallenge(
            nextQuestion.id
          );

          setChoice(null);

          setShortAnswer('');

          setFeedback(null);

          return;

        }


        /*
         * No more questions
         */

        setChallenge(null);

        setChoice(null);

        setShortAnswer('');

        setFeedback(null);

      }, 700);

    }, [
      currentChallenge,
      choice,
      shortAnswer,
      solved,
      activeChallenges,
      whiteboardChallenges,
      drawerChallenges,
    ]);


  /*
   * =========================================================
   * FINISHED SCREEN
   * =========================================================
   */

  if (finished) {

    return (

      <main className="game-shell fixed inset-0 z-50 flex min-h-screen items-center justify-center p-6">

        <div className="panel max-w-2xl p-10 text-center">

          <div className="text-3xl font-black text-yellow-200">

            CONGRATULATIONS!

          </div>

          <div className="mt-5 text-xl font-black text-cyan-200">

            YOU HAVE COMPLETED THE HEALTHCARE ENGLISH CHALLENGE.

          </div>

          <p className="mt-5 text-sm text-slate-400">

            You explored all four layouts
            and completed all healthcare
            English challenges.

          </p>

          <button
            className="retro-btn mt-7 px-5 py-3"
            onClick={() =>
              location.reload()
            }
          >

            PLAY AGAIN

          </button>

        </div>

      </main>

    );

  }


  /*
   * =========================================================
   * MAIN GAME
   * =========================================================
   */

  return (

    <main className="game-shell fixed inset-0 z-50 flex h-screen w-screen items-center justify-center overflow-hidden">

      <div className="flex h-full w-full items-center justify-center">

        <div className="relative aspect-[4/3] h-[100vh] max-h-screen w-auto max-w-screen overflow-hidden border-4 border-[#20272e] bg-[#59606a] shadow-2xl">


          {/* =================================================
              ROOM
              ================================================= */}

          <Room
            roomObjects={
              visibleObjects
            }

            nearId={
              nearObj?.id ?? null
            }

            collected={
              new Set()
            }

            onInteract={
              (object) => {

                if (
                  !object.interactive ||
                  challenge ||
                  fakeMessage ||
                  transitioning
                ) {

                  return;

                }


                const interactionType =
  getInteractionType(
    nearObj
  );


/*
 * =====================================================
 * LAYOUT 2 — TEACHER DESK PASSWORD
 * =====================================================
 */

if (
  layout === 2 &&
  nearObj.id === 'l2_teacher_desk'
) {

  if (teacherDeskUnlocked) {

    openNextChallenge();

    return;

  }

  setPasswordOpen(true);

  setPasswordInput('');

  return;

}


/*
 * REAL CHALLENGE
 */

if (
  interactionType === 'whiteboard' ||
  interactionType === 'drawer'
) {

  openNextChallenge();

  return;

}

                  
                /*
                 * REAL CHALLENGE
                 */
                  
                if (
                  interactionType ===
                    'whiteboard' ||
                  interactionType ===
                    'drawer'
                ) {

                  openNextChallenge();

                  return;

                }


                /*
                 * FAKE INTERACTION
                 */

                /*
 * CLUE INTERACTION
 */

if (
  object.clueId
) {

  collectClue(
    object
  );

  return;

}


/*
 * FAKE INTERACTION
 */

setFakeMessage(
  getFakeInteractionMessage(
    object.id
  )
);

              }
            }

            layout={
              layout
            }

          />


          {/* =================================================
              DEBUG COLLISION VISUALIZER
              =================================================
              
              F2 = ON/OFF
              
              This draws the actual collision rectangles
              directly from the RoomObject x/y/w/h values.
              ================================================= */}

          {debugCollision && (

            <div
              className="pointer-events-none absolute inset-0 z-[35]"
              aria-hidden="true"
            >

              {visibleObjects
                .filter(
                  (object) =>
                    object.solid
                )
                .map(
                  (object) => {

                    const isInteractive =
                      object.interactive;

                    const isNear =
                      nearObj?.id ===
                      object.id;

                    return (

                      <div
                        key={`debug-${object.id}`}
                        className={`absolute box-border border-2 ${
                          isNear
                            ? 'border-yellow-300 bg-yellow-300/20'
                            : isInteractive
                              ? 'border-cyan-300 bg-cyan-300/10'
                              : 'border-red-400 bg-red-400/10'
                        }`}
                        style={{
                          left: `${object.x}%`,
                          top: `${object.y}%`,
                          width: `${object.w}%`,
                          height: `${object.h}%`,
                        }}
                      >

                        <div
                          className={`absolute -top-4 left-0 whitespace-nowrap px-1 text-[7px] font-black ${
                            isNear
                              ? 'bg-yellow-300 text-black'
                              : isInteractive
                                ? 'bg-cyan-300 text-black'
                                : 'bg-red-400 text-black'
                          }`}
                        >

                          {object.name}

                          {isNear &&
                            ' [NEAR]'}

                        </div>

                      </div>

                    );

                  }
                )}

            </div>

          )}


          {/* =================================================
              DEBUG HUD
              ================================================= */}

          {debugCollision && (

            <div className="pointer-events-none absolute right-3 top-3 z-[60] border-2 border-yellow-300 bg-black/85 px-3 py-2 text-[9px] font-black text-yellow-200">

              <div>
                COLLISION DEBUG: ON
              </div>

              <div className="mt-1 text-red-300">
                RED = SOLID
              </div>

              <div className="text-cyan-300">
                CYAN = INTERACTIVE
              </div>

              <div className="text-yellow-200">
                YELLOW = NEAREST
              </div>

              <div className="mt-1 text-white">
                PRESS F2 TO HIDE
              </div>

            </div>

          )}


          {/* =================================================
              PLAYER
              ================================================= */}

          <Player
            x={pos.x}
            y={pos.y}
            direction={direction}
            walking={walking}
            frame={frame}
          />


          {/* =================================================
              HUD
              ================================================= */}

          <div className="absolute left-3 top-3 z-40 border-2 border-[#20272e] bg-black/75 px-3 py-2 text-[10px] font-black text-white">

            <div>
              LAYOUT {layout}
            </div>

            <div className="mt-1 text-cyan-200">

              CHALLENGES:{' '}
              {solvedInCurrentLayout}/
              {activeChallenges.length}

            </div>

            {!currentLayoutCompleted && (

              <div className="mt-1 text-yellow-200">

                COMPLETE ALL CHALLENGES

              </div>

            )}

            {currentLayoutCompleted &&
              layout < 4 && (

                <div className="mt-1 text-green-300">

                  EXIT UNLOCKED

                </div>

            )}

          </div>


          {/* =================================================
              E INTERACTION PROMPT
              ================================================= */}

          {nearObj &&
            !challenge &&
            !fakeMessage &&
            !transitioning && (

              <div className="absolute bottom-6 left-1/2 z-50 -translate-x-1/2 border-2 border-yellow-300 bg-black/85 px-5 py-3 text-center text-xs font-black text-yellow-100">

                [E] INTERACT —{' '}
                {nearObj.name}

              </div>

          )}

          {/* =================================================
    TEACHER DESK PASSWORD
    ================================================= */}

{passwordOpen &&
  layout === 2 &&
  !challenge &&
  !transitioning && (

    <div className="absolute inset-0 z-[95] flex items-center justify-center bg-black/70 p-6">

      <div className="w-full max-w-xl border-4 border-[#20272e] bg-[#111820] shadow-2xl">

        <div className="border-b-4 border-yellow-300 bg-black/80 px-5 py-4">

          <div className="text-[10px] font-black tracking-widest text-yellow-300">

            TEACHER DESK

          </div>

          <div className="mt-1 text-xl font-black text-white">

            ENTER PASSWORD

          </div>

        </div>


        <div className="px-6 py-8">

          <div className="border-2 border-slate-600 bg-black/50 p-5">

            <p className="text-center text-sm font-bold leading-relaxed text-slate-200">

              You found several hidden letters around the classroom.

              <br />

              Put the letters together to unlock the Teacher Desk.

            </p>

          </div>


          <input
            autoFocus
            type="text"
            value={passwordInput}
            onChange={(event) =>
              setPasswordInput(
                event.target.value
              )
            }
            onKeyDown={(event) => {

              if (
                event.key === 'Enter'
              ) {

                submitTeacherDeskPassword();

              }

              if (
                event.key === 'Escape'
              ) {

                setPasswordOpen(false);

                setPasswordInput('');

              }

            }}
            placeholder="ENTER PASSWORD"
            className="mt-6 w-full border-4 border-cyan-300 bg-black px-4 py-4 text-center text-lg font-black uppercase tracking-[0.3em] text-white outline-none placeholder:text-slate-600 focus:border-yellow-300"
          />


          <div className="mt-6 flex justify-center gap-3">

            <button
              type="button"
              className="retro-btn px-7 py-3 text-xs font-black"
              onClick={
                submitTeacherDeskPassword
              }
            >

              UNLOCK

            </button>


            <button
              type="button"
              className="border-2 border-slate-500 bg-black px-7 py-3 text-xs font-black text-slate-300"
              onClick={() => {

                setPasswordOpen(false);

                setPasswordInput('');

              }}
            >

              CANCEL

            </button>

          </div>


          <div className="mt-5 text-center text-[9px] font-black text-slate-500">

            PRESS ENTER TO SUBMIT • ESC TO CANCEL

          </div>

        </div>

      </div>

    </div>

)}


          {/* =================================================
              FAKE INTERACTION POPUP
              ================================================= */}

          {fakeMessage &&
            !challenge &&
            !transitioning && (

              <div className="absolute inset-0 z-[90] flex items-center justify-center bg-black/60 p-6">

                <div className="w-full max-w-xl border-4 border-[#20272e] bg-[#111820] shadow-2xl">

                  <div className="border-b-4 border-cyan-300 bg-black/80 px-5 py-4">

                    <div className="text-[10px] font-black tracking-widest text-cyan-300">

                      INTERACTION

                    </div>

                    <div className="mt-1 text-xl font-black text-white">

                      {nearObj?.name ?? 'OBJECT'}

                    </div>

                  </div>


                  <div className="px-6 py-8">

                    <div className="border-2 border-slate-600 bg-black/50 p-6 text-center">

                      <p className="whitespace-pre-line text-base font-bold leading-relaxed text-slate-100">

                        {fakeMessage}

                      </p>

                    </div>


                    <div className="mt-6 text-center text-[10px] font-black text-slate-400">

                      PRESS ESC TO CLOSE

                    </div>


                    <div className="mt-4 flex justify-center">

                      <button
                        type="button"
                        className="retro-btn px-8 py-3 text-xs font-black"
                        onClick={() =>
                          setFakeMessage(null)
                        }
                      >

                        CLOSE

                      </button>

                    </div>

                  </div>

                </div>

              </div>

          )}


          {/* =================================================
              LOCKED MESSAGE
              ================================================= */}

          {(
            (layout === 1 &&
              pos.x < 12 &&
              pos.y > 82 &&
              !currentLayoutCompleted) ||

            (layout === 2 &&
              pos.x < 12 &&
              pos.y > 82 &&
              !currentLayoutCompleted) ||

            (layout === 3 &&
              pos.x > 42 &&
              pos.x < 58 &&
              pos.y < 18 &&
              !currentLayoutCompleted) ||

            (layout === 4 &&
              pos.x >= 12 &&
              pos.x <= 29 &&
              pos.y >= 29 &&
              pos.y <= 32 &&
              !currentLayoutCompleted)

          ) && (

            <div className="absolute bottom-6 left-1/2 z-50 -translate-x-1/2 border-2 border-red-400 bg-black/85 px-5 py-3 text-center text-xs font-black text-red-200">

              🔒 EXIT LOCKED

              <div className="mt-1 text-[9px] text-white">

                COMPLETE ALL CHALLENGES FIRST

              </div>

            </div>

          )}


          {/* =================================================
              ROOM TRANSITION
              ================================================= */}

          {transitioning && (

            <div className="absolute inset-0 z-[100] flex items-center justify-center bg-black/70">

              <div className="text-center">

                <div className="text-2xl font-black text-yellow-200">

                  ENTERING NEXT ROOM...

                </div>

                <div className="mt-2 text-xs text-slate-300">

                  {layout < 4
                    ? `LAYOUT ${layout + 1}`
                    : 'RETURNING'}

                </div>

              </div>

            </div>

          )}

          {/* =================================================
    TEACHER DESK PASSWORD
    ================================================= */}

{passwordOpen &&
  layout === 2 &&
  !challenge &&
  !transitioning && (

    <div className="absolute inset-0 z-[95] flex items-center justify-center bg-black/70 p-6">

      <div className="w-full max-w-xl border-4 border-[#20272e] bg-[#111820] shadow-2xl">

        <div className="border-b-4 border-cyan-300 bg-black/80 px-5 py-4">

          <div className="text-[10px] font-black tracking-widest text-cyan-300">

            TEACHER DESK

          </div>

          <div className="mt-1 text-xl font-black text-white">

            PASSWORD REQUIRED

          </div>

        </div>

        <div className="px-6 py-8">

          <div className="border-2 border-slate-600 bg-black/50 p-6">

            <p className="text-center text-sm font-bold leading-relaxed text-slate-200">

              Enter the password you discovered
              from the hidden clues.

            </p>

            <input
              type="text"
              value={passwordInput}
              onChange={(event) =>
                setPasswordInput(
                  event.target.value
                )
              }
              onKeyDown={(event) => {

                if (
                  event.key === 'Enter'
                ) {

                  submitTeacherDeskPassword();

                }

                if (
                  event.key === 'Escape'
                ) {

                  setPasswordOpen(false);

                  setPasswordInput('');

                }

              }}
              autoFocus
              placeholder="ENTER PASSWORD"
              className="mt-6 w-full border-2 border-cyan-300 bg-black px-4 py-4 text-center text-lg font-black uppercase tracking-widest text-white outline-none placeholder:text-slate-600"
            />

          </div>

          <div className="mt-6 flex justify-center gap-3">

            <button
              type="button"
              className="retro-btn px-6 py-3 text-xs font-black"
              onClick={
                submitTeacherDeskPassword
              }
            >

              UNLOCK

            </button>

            <button
              type="button"
              className="retro-btn px-6 py-3 text-xs font-black"
              onClick={() => {

                setPasswordOpen(false);

                setPasswordInput('');

              }}
            >

              CANCEL

            </button>

          </div>

          <div className="mt-5 text-center text-[10px] font-black text-slate-400">

            PRESS ENTER TO SUBMIT • ESC TO CLOSE

          </div>

        </div>

      </div>

    </div>

)}

          {/* =================================================
              REAL CHALLENGE MODAL
              ================================================= */}

          {challenge &&
            currentChallenge && (

              <ChallengeModal

                challenge={
                  currentChallenge
                }

                index={
                  activeChallenges.findIndex(
                    (
                      challengeItem
                    ) =>
                      challengeItem.id ===
                      currentChallenge.id
                  ) + 1
                }

                total={
                  activeChallenges.length
                }

                choice={
                  choice
                }

                setChoice={
                  setChoice
                }

                shortAnswer={
                  shortAnswer
                }

                setShortAnswer={
                  setShortAnswer
                }

                onSubmit={
                  submit
                }

                onContinue={
                  continueToWhiteboardQuestions
                }

                feedback={
                  feedback
                }

                onClose={() => {

                  setChallenge(
                    null
                  );

                  setChoice(
                    null
                  );

                  setFeedback(
                    null
                  );

                }}

              />

            )}

        </div>

      </div>

    </main>

  );

}